import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_conv2d(torch::Tensor x, torch::Tensor w,
                           int64_t stride, int64_t padding, int64_t dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
#define TILE_H 16
#define TILE_W 16
#define REG_W 8   // register blocking factor along output width (increased for higher arithmetic intensity per thread)
__global__ void cute_conv2d_kernel(
    const float* __restrict__ x_ptr,
    const float* __restrict__ w_ptr,
    float* __restrict__ y_ptr,
    int N, int C_in, int H, int W,
    int C_out, int K,
    int stride, int padding, int dilation,
    int H_out, int W_out,
    int smem_h, int smem_w)
{
    // Wrap global memory as CUTE tensors (row-major / C-contiguous layouts)
    Tensor gX = make_tensor(make_gmem_ptr(x_ptr),
                             make_shape(N, C_in, H, W),
                             make_stride(C_in * H * W, H * W, W, 1));
    Tensor gW = make_tensor(make_gmem_ptr(w_ptr),
                             make_shape(C_out, C_in, K, K),
                             make_stride(C_in * K * K, K * K, K, 1));
    Tensor gY = make_tensor(make_gmem_ptr(y_ptr),
                             make_shape(N, C_out, H_out, W_out),
                             make_stride(C_out * H_out * W_out, H_out * W_out, W_out, 1));
    int bz = blockIdx.z;
    int n  = bz / C_out;
    int co = bz % C_out;
    int out_w0 = blockIdx.x * (TILE_W * REG_W);
    int out_h0 = blockIdx.y * TILE_H;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int out_h = out_h0 + ty;
    extern __shared__ float smem[];
    float* w_smem_raw  = smem;                    // C_in * K * K
    float* in_smem_raw = smem + C_in * K * K;      // 2 * smem_h * smem_w (double buffered)
    int tile_size = smem_h * smem_w;
    // CUTE tensors over shared memory (row-major)
    Tensor sW = make_tensor(make_smem_ptr(w_smem_raw),
                             make_shape(C_in, K, K),
                             make_stride(K * K, K, 1));
    Tensor sIn0 = make_tensor(make_smem_ptr(in_smem_raw),
                              make_shape(smem_h, smem_w),
                              make_stride(smem_w, 1));
    Tensor sIn1 = make_tensor(make_smem_ptr(in_smem_raw + tile_size),
                              make_shape(smem_h, smem_w),
                              make_stride(smem_w, 1));
    int tid = ty * TILE_W + tx;
    int nthreads = TILE_W * TILE_H;
    // Load weights for this output channel into shared memory
    int wsize = C_in * K * K;
    for (int i = tid; i < wsize; i += nthreads) {
        int ci = i / (K * K);
        int rem = i % (K * K);
        int kh = rem / K;
        int kw = rem % K;
        sW(ci, kh, kw) = gW(co, ci, kh, kw);
    }
    float acc[REG_W];
    #pragma unroll
    for (int r = 0; r < REG_W; ++r) acc[r] = 0.f;
    int in_h0 = out_h0 * stride - padding;
    int in_w0 = out_w0 * stride - padding;
    // Prefetch first input channel tile into buffer 0 (double-buffered pipelined loads)
    for (int i = tid; i < tile_size; i += nthreads) {
        int r = i / smem_w;
        int c = i % smem_w;
        int gh = in_h0 + r;
        int gw = in_w0 + c;
        float v = 0.f;
        if (gh >= 0 && gh < H && gw >= 0 && gw < W) {
            v = gX(n, 0, gh, gw);
        }
        sIn0(r, c) = v;
    }
    __syncthreads();
    for (int ci = 0; ci < C_in; ++ci) {
        bool cur_is0 = ((ci & 1) == 0);
        auto& sInCur = cur_is0 ? sIn0 : sIn1;
        // Prefetch next channel's tile while computing on the current buffer
        if (ci + 1 < C_in) {
            auto& sInNext = cur_is0 ? sIn1 : sIn0;
            int ci_next = ci + 1;
            for (int i = tid; i < tile_size; i += nthreads) {
                int r = i / smem_w;
                int c = i % smem_w;
                int gh = in_h0 + r;
                int gw = in_w0 + c;
                float v = 0.f;
                if (gh >= 0 && gh < H && gw >= 0 && gw < W) {
                    v = gX(n, ci_next, gh, gw);
                }
                sInNext(r, c) = v;
            }
        }
        if (out_h < H_out) {
            #pragma unroll
            for (int kh = 0; kh < K; ++kh) {
                int rrow = ty * stride + kh * dilation;
                #pragma unroll
                for (int kw = 0; kw < K; ++kw) {
                    float wv = sW(ci, kh, kw);
                    #pragma unroll
                    for (int r = 0; r < REG_W; ++r) {
                        int c_local = (r * TILE_W + tx) * stride + kw * dilation;
                        acc[r] += sInCur(rrow, c_local) * wv;
                    }
                }
            }
        }
        __syncthreads();
    }
    if (out_h < H_out) {
        #pragma unroll
        for (int r = 0; r < REG_W; ++r) {
            int out_w = out_w0 + r * TILE_W + tx;
            if (out_w < W_out) {
                gY(n, co, out_h, out_w) = acc[r];
            }
        }
    }
}
torch::Tensor cute_conv2d(torch::Tensor x, torch::Tensor w,
                           int64_t stride, int64_t padding, int64_t dilation) {
    TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");
    TORCH_CHECK(w.dim() == 4, "w must be 4D (Cout,Cin,K,K)");
    TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    auto x_c = x.contiguous();
    auto w_c = w.contiguous();
    int N     = (int)x_c.size(0);
    int C_in  = (int)x_c.size(1);
    int H     = (int)x_c.size(2);
    int W     = (int)x_c.size(3);
    int C_out = (int)w_c.size(0);
    int K     = (int)w_c.size(2);
    TORCH_CHECK((int)w_c.size(1) == C_in, "weight in_channels mismatch");
    TORCH_CHECK((int)w_c.size(3) == K, "weight must be square kernel");
    int s = (int)stride;
    int p = (int)padding;
    int d = (int)dilation;
    int H_out = (H + 2 * p - d * (K - 1) - 1) / s + 1;
    int W_out = (W + 2 * p - d * (K - 1) - 1) / s + 1;
    auto y = torch::empty({N, C_out, H_out, W_out}, x_c.options());
    int smem_h = (TILE_H - 1) * s + (K - 1) * d + 1;
    int smem_w = (TILE_W * REG_W - 1) * s + (K - 1) * d + 1;
    size_t smem_bytes = (size_t)(C_in * K * K + 2 * smem_h * smem_w) * sizeof(float);
    dim3 block(TILE_W, TILE_H);
    dim3 grid((W_out + (TILE_W * REG_W) - 1) / (TILE_W * REG_W),
              (H_out + TILE_H - 1) / TILE_H,
              N * C_out);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(cute_conv2d_kernel,
                              cudaFuncAttributeMaxDynamicSharedMemorySize,
                              (int)smem_bytes);
    }
    cute_conv2d_kernel<<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(), w_c.data_ptr<float>(), y.data_ptr<float>(),
        N, C_in, H, W, C_out, K, s, p, d, H_out, W_out, smem_h, smem_w);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE conv2d launch failed");
    return y;
}
"""

cute_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv2d"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/workspace/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        assert groups == 1, "This custom CUTE kernel only supports groups=1"
        assert bias == False, "This custom CUTE kernel only supports bias=False"

        # Reuse nn.Conv2d only for parameter initialization semantics
        ref_conv = nn.Conv2d(in_channels, out_channels, (kernel_size, kernel_size),
                              stride=stride, padding=padding, dilation=dilation,
                              groups=groups, bias=bias)
        self.weight = nn.Parameter(ref_conv.weight.data.clone())

        self.stride = stride
        self.padding = padding
        self.dilation = dilation

        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous().float()
        w = self.weight.to(device=x.device, dtype=torch.float32).contiguous()
        return self._ext.cute_conv2d(x, w, self.stride, self.padding, self.dilation)

